package com.booksyde.service; import com.booksyde.dto.response.PublisherDashboardResponse; import com.booksyde.mapper.BookMapper; import com.booksyde.repository.*; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class PublisherService {private final MangaRepository mangas; private final VolumeRepository volumes; public PublisherService(MangaRepository mangas,VolumeRepository volumes){this.mangas=mangas;this.volumes=volumes;} @Transactional(readOnly=true) public PublisherDashboardResponse dashboard(UUID userId){var works=mangas.findAllByCreatorIdOrderByCreatedAtDesc(userId); long volumeCount=works.stream().mapToLong(w->volumes.countByMangaId(w.getId())).sum(); long views=works.stream().mapToLong(w->w.getViewCount()).sum(); return new PublisherDashboardResponse(works.size(),volumeCount,views,works.stream().limit(5).map(BookMapper::toResponse).toList());}}
